def solve(readings, target):
    prefix_counts = {0: 1}
    curr_sum = 0
    count = 0
    for r in readings:
        curr_sum += r
        diff = curr_sum - target
        if diff in prefix_counts:
            count += prefix_counts[diff]
        prefix_counts[curr_sum] = prefix_counts.get(curr_sum, 0) + 1
    return count
